'use client';

import React, { useEffect, useCallback, useState, useRef, Suspense } from 'react';
import { motion } from 'framer-motion';
import { useGame } from '@/hooks/useGame';
import { GameHeader } from '@/components/game/GameHeader';
import { GameKeyboard } from '@/components/game/GameKeyboard';
import { WordleBoard } from '@/components/game/WordleBoard';
import { GameEndModal } from '@/components/game/GameEndModal';
import { ErrorToast } from '@/components/game/ErrorToast';
import { GAMES } from '@/data/games';
import { GameInstructions } from '@/components/game/GameInstructions';
import { SettingsModal } from '@/components/game/SettingsModal';
import { ResumeGameModal } from '@/components/game/ResumeGameModal';
import { ChallengeModal } from '@/components/game/ChallengeModal';
import { InfoModal } from '@/components/game/InfoModal';
import { StatsModal } from '@/components/game/StatsModal';
import { useGameSettings } from '@/context/GameSettingsContext';
import { useAuth } from '@/hooks/useAuth';
import { savedGameService } from '@/services/savedGameService';
import { challengeService } from '@/services/challengeService';
import { formatTime } from '@/utils/timeUtils';
import { shareContent } from '@/utils/shareUtils';
import { useRouter, useSearchParams } from 'next/navigation';

const WORD_LENGTH = 5;
const MAX_GUESSES = 6;
const GAME_NAME = 'wordle';

const TURKISH_LETTERS = new Set(
    'ABCÇDEFGĞHIİJKLMNOÖPRSŞTUÜVYZabcçdefgğhıijklmnoöprsştuüvyz'.split('')
);

function WordlePageContent() {
    const searchParams = useSearchParams();
    const challengeId = searchParams.get('challengeId');
    const [showInfoModal, setShowInfoModal] = useState(false);
    const [showStatsModal, setShowStatsModal] = useState(false);
    const [showSettingsModal, setShowSettingsModal] = useState(false);
    const [showResultModal, setShowResultModal] = useState(false);
    const [showResumeModal, setShowResumeModal] = useState(false);
    const [showChallengeModal, setShowChallengeModal] = useState(false);
    const [toastMessage, setToastMessage] = useState<string | null>(null);
    const [savedElapsedTime, setSavedElapsedTime] = useState(0);
    const [savedGuessesCount, setSavedGuessesCount] = useState(0);

    const cloudCheckDoneRef = useRef(false);
    const savedCloudStateRef = useRef<{ state: import('@/services/savedGameService').SavedGameState; elapsedTime: number } | null>(null);

    const isPaused = showInfoModal || showStatsModal || showSettingsModal || showResultModal || showResumeModal || showChallengeModal;

    const { isAuthenticated } = useAuth();
    const router = useRouter();

    const {
        status,
        targetWord,
        guesses,
        currentGuess,
        currentRow,
        keyboardState,
        error,
        maxGuesses,
        wordLength,
        elapsedTime,
        joker,
        score,
        isChallengeMode,
        activeChallengeId,
        isCustomWord,
        startNewGame,
        handleKeyPress,
        handleDelete,
        handleEnter,
        useJoker,
        saveGameToCloud,
        loadGameFromCloud,
        deleteCloudSave,
    } = useGame({
        initialWordLength: WORD_LENGTH,
        initialMaxGuesses: MAX_GUESSES,
        isPaused,
        challengeId,
    });

    const [shakeRow, setShakeRow] = useState(false);
    const { difficulty } = useGameSettings();

    useEffect(() => {
        if (cloudCheckDoneRef.current || !isAuthenticated) {
            startNewGame(WORD_LENGTH, MAX_GUESSES);
        }
    }, [startNewGame, difficulty, isAuthenticated]);

    useEffect(() => {
        if (!isAuthenticated || cloudCheckDoneRef.current) return;

        const checkCloudSave = async () => {
            try {
                const savedGame = await savedGameService.getSavedGame(GAME_NAME);
                if (savedGame) {
                    setSavedElapsedTime(savedGame.elapsed_time);
                    setSavedGuessesCount(savedGame.state.guesses.length);
                    savedCloudStateRef.current = {
                        state: savedGame.state,
                        elapsedTime: savedGame.elapsed_time,
                    };
                    setShowResumeModal(true);
                } else {
                    startNewGame(WORD_LENGTH, MAX_GUESSES);
                }
            } catch {
                startNewGame(WORD_LENGTH, MAX_GUESSES);
            }
            cloudCheckDoneRef.current = true;
        };

        checkCloudSave();
    }, [isAuthenticated, startNewGame]);

    useEffect(() => {
        if (status === 'won' || status === 'lost') {
            const timer = setTimeout(() => setShowResultModal(true), 1200);
            if (isAuthenticated) {
                deleteCloudSave(GAME_NAME).catch(console.error);
            }
            if (isChallengeMode && activeChallengeId) {
                challengeService.updateChallengeResult(activeChallengeId, score, guesses.length).catch(console.error);
            }
            return () => clearTimeout(timer);
        }
    }, [status, isAuthenticated, deleteCloudSave, isChallengeMode, activeChallengeId, score, guesses.length]);

    useEffect(() => {
        if (error) {
            setShakeRow(true);
            const timer = setTimeout(() => setShakeRow(false), 500);
            return () => clearTimeout(timer);
        }
    }, [error]);

    const handlePhysicalKeyboard = useCallback((e: KeyboardEvent) => {
        if (status !== 'playing' || isPaused) return;
        if (e.key === 'Enter') {
            e.preventDefault();
            handleEnter();
        } else if (e.key === 'Backspace') {
            e.preventDefault();
            handleDelete();
        } else if (e.key.length === 1 && TURKISH_LETTERS.has(e.key)) {
            e.preventDefault();
            handleKeyPress(e.key);
        }
    }, [status, handleEnter, handleDelete, handleKeyPress, isPaused]);

    useEffect(() => {
        window.addEventListener('keydown', handlePhysicalKeyboard);
        return () => window.removeEventListener('keydown', handlePhysicalKeyboard);
    }, [handlePhysicalKeyboard]);

    const handleRestart = () => {
        setShowResultModal(false);
        startNewGame(WORD_LENGTH, MAX_GUESSES);
    };

    const handleSaveGame = async () => {
        const success = await saveGameToCloud(GAME_NAME);
        if (success) {
            setToastMessage('Oyun kaydedildi!');
            setTimeout(() => router.push('/'), 800);
        } else {
            setToastMessage('Oyun kaydedilemedi!');
            setTimeout(() => setToastMessage(null), 3000);
        }
    };

    const handleResumeGame = () => {
        setShowResumeModal(false);
        if (savedCloudStateRef.current) {
            loadGameFromCloud(savedCloudStateRef.current.state, savedCloudStateRef.current.elapsedTime);
            savedCloudStateRef.current = null;
        }
    };

    const handleNewGameFromModal = async () => {
        setShowResumeModal(false);
        savedCloudStateRef.current = null;
        await deleteCloudSave(GAME_NAME);
        startNewGame(WORD_LENGTH, MAX_GUESSES);
    };

    const handleShare = async () => {
        const result = await shareContent({
            title: 'Kelime Oyunları - Wordle',
            text: 'Kelime Oyunları\'nda Wordle oyna!',
            url: window.location.href,
        });
        if (result.success && result.type === 'copy') {
            setToastMessage('Bağlantı kopyalandı!');
            setTimeout(() => setToastMessage(null), 3000);
        }
    };

    const handleResultShare = async () => {
        const resultText = status === 'won'
            ? `Wordle'ı ${guesses.length}/${maxGuesses} denemede buldum! 🏆`
            : `Wordle'da şansım bu sefer yaver gitmedi. 🧩`;
        const result = await shareContent({
            title: 'Wordle Sonucum',
            text: resultText,
            url: window.location.href,
        });
        if (result.success && result.type === 'copy') {
            setToastMessage('Sonuç kopyalandı!');
            setTimeout(() => setToastMessage(null), 3000);
        }
    };

    if (status === 'loading' || status === 'idle') {
        return (
            <div className="flex flex-col h-[100dvh] overflow-hidden bg-bg">
                <GameHeader
                    title="WORDLE"
                    onHelp={() => setShowInfoModal(true)}
                    onStats={() => setShowStatsModal(true)}
                    onSettings={() => setShowSettingsModal(true)}
                    onShare={handleShare}
                    onSave={handleSaveGame}
                    onChallenge={() => setShowChallengeModal(true)}
                    isLoggedIn={isAuthenticated}
                    isChallengeMode={isChallengeMode}
                    gameStatus={status}
                    onJoker={useJoker}
                    jokerUsed={joker.used}
                    timerText={formatTime(elapsedTime)}
                />
                <div className="flex-1 flex items-center justify-center">
                    <motion.div
                        animate={{ rotate: 360 }}
                        transition={{ repeat: Infinity, duration: 1 }}
                        className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full"
                    />
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-[100dvh] flex flex-col bg-bg text-text-main overflow-y-auto w-full">
            <div className="flex flex-col min-h-[100dvh] shrink-0">
                <GameHeader
                    title="WORDLE"
                    onHelp={() => setShowInfoModal(true)}
                    onStats={() => setShowStatsModal(true)}
                    onSettings={() => setShowSettingsModal(true)}
                    onShare={handleShare}
                    onSave={handleSaveGame}
                    onChallenge={() => setShowChallengeModal(true)}
                    isLoggedIn={isAuthenticated}
                    isChallengeMode={isChallengeMode}
                    gameStatus={status}
                    onJoker={useJoker}
                    jokerUsed={joker.used}
                    timerText={formatTime(elapsedTime)}
                />

                {isChallengeMode && (
                    <div className="mx-4 mt-1 px-4 py-2 bg-primary/10 border border-primary/30 rounded-xl text-center">
                        <p className="text-primary text-sm font-bold flex items-center justify-center gap-2">⚔️ Bir meydan okuma oynuyorsunuz!</p>
                    </div>
                )}

                <ErrorToast message={error || toastMessage || ''} />

                <div className="flex-1 flex items-center justify-center px-4 py-2">
                    <WordleBoard
                        guesses={guesses}
                        currentGuess={currentGuess}
                        currentRow={currentRow}
                        wordLength={wordLength}
                        maxGuesses={maxGuesses}
                        shakeRow={shakeRow}
                        status={status}
                    />
                </div>

                <div className="px-1 sm:px-2 pb-4 sm:pb-6 shrink-0">
                    <GameKeyboard
                        onKeyPress={handleKeyPress}
                        onEnter={handleEnter}
                        onDelete={handleDelete}
                        keyStates={keyboardState}
                    />
                </div>
            </div>

            <section className="w-full max-w-2xl mx-auto px-6 py-12 md:py-16 border-t border-surface/50">
                <GameInstructions
                    instructions={GAMES.find(g => g.id === 'wordle')!.instructions}
                    title="Wordle"
                />
            </section>

            <GameEndModal
                isOpen={showResultModal}
                status={status}
                guessesCount={guesses.length}
                maxGuesses={maxGuesses}
                targetWord={targetWord}
                isCustomWord={isCustomWord}
                onRestart={handleRestart}
                onShare={handleResultShare}
                score={score}
            />

            <ResumeGameModal
                isOpen={showResumeModal}
                elapsedTime={savedElapsedTime}
                guessesCount={savedGuessesCount}
                onResume={handleResumeGame}
                onNewGame={handleNewGameFromModal}
            />

            {showInfoModal && <InfoModal onClose={() => setShowInfoModal(false)} />}
            {showStatsModal && <StatsModal onClose={() => setShowStatsModal(false)} />}

            <SettingsModal
                isOpen={showSettingsModal}
                onClose={() => setShowSettingsModal(false)}
            />

            <ChallengeModal
                isOpen={showChallengeModal}
                onClose={() => setShowChallengeModal(false)}
                gameName={GAME_NAME}
                wordLength={WORD_LENGTH}
            />
        </div>
    );
}

function ChallengeAuthGate() {
    const searchParams = useSearchParams();
    const challengeId = searchParams.get('challengeId');
    const { isAuthenticated } = useAuth();
    const router = useRouter();

    if (challengeId && !isAuthenticated) {
        const redirectUrl = `/games/wordle?challengeId=${challengeId}`;
        return (
            <div className="flex flex-col h-[100dvh] overflow-hidden bg-bg items-center justify-center px-6 text-center">
                <div className="max-w-sm w-full">
                    <div className="w-20 h-20 bg-primary/20 rounded-full flex items-center justify-center mx-auto mb-6">
                        <span className="text-4xl">⚔️</span>
                    </div>
                    <h2 className="text-2xl font-black text-text-main mb-3 tracking-tight">Meydan Okuma!</h2>
                    <p className="text-text-secondary text-sm mb-8 leading-relaxed">
                        Bir arkadaşın sana meydan okudu! Oynayabilmek için giriş yapman veya üye olman gerekiyor.
                    </p>
                    <div className="flex flex-col gap-3">
                        <button
                            onClick={() => router.push(`/login?redirect=${encodeURIComponent(redirectUrl)}`)}
                            className="w-full bg-primary text-bg font-black py-3.5 rounded-2xl hover:scale-[1.02] transition-transform shadow-lg shadow-primary/20"
                        >
                            GİRİŞ YAP
                        </button>
                        <button
                            onClick={() => router.push(`/register?redirect=${encodeURIComponent(redirectUrl)}`)}
                            className="w-full bg-surface-hover text-text-main font-bold py-3.5 rounded-2xl hover:bg-surface-mid transition-colors border border-surface-hover"
                        >
                            ÜYE OL
                        </button>
                        <button onClick={() => router.push('/')} className="text-text-muted text-sm mt-2 hover:text-text-main transition-colors">Ana Sayfaya Dön</button>
                    </div>
                </div>
            </div>
        );
    }
    return <WordlePageContent />;
}

export default function WordlePage() {
    return (
        <Suspense fallback={
            <div className="flex flex-col h-[100dvh] overflow-hidden bg-bg">
                <div className="flex-1 flex items-center justify-center">
                    <motion.div
                        animate={{ rotate: 360 }}
                        transition={{ repeat: Infinity, duration: 1 }}
                        className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full"
                    />
                </div>
            </div>
        }>
            <ChallengeAuthGate />
        </Suspense>
    );
}

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Swords, BarChart3, Gamepad2, SendHorizonal, Users, Trophy, Star } from 'lucide-react';
import Link from 'next/link';
import { StatCard } from '@/components/game/StatCard';
import { ProfileData } from '@/services/profileService';

const GAME_LABELS: Record<string, string> = {
    wordle: 'Wordle',
    anagram: 'Anagram',
    hangman: 'Adam Asmaca',
    quiz: 'Kelime Bilgi',
};

interface ChallengeStatsTabProps {
    profile: ProfileData;
}

export function ChallengeStatsTab({ profile }: ChallengeStatsTabProps) {
    if (profile.isGuest) {
        return (
            <div className="bg-surface border-2 border-surface-mid rounded-2xl p-10 text-center">
                <Swords
                    size={44}
                    className="text-text-secondary mx-auto mb-3 opacity-40"
                />
                <p className="text-text-secondary text-sm mb-4">
                    Meydan okuma istatistiklerini görmek için giriş yap!
                </p>
                <div className="flex items-center justify-center gap-3">
                    <Link
                        href="/login"
                        className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-bold bg-primary text-bg rounded-full hover:scale-105 transition-transform shadow-[0_0_15px_rgba(34,211,238,0.3)]"
                    >
                        Giriş Yap
                    </Link>
                    <Link
                        href="/register"
                        className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-bold bg-surface text-text-main border-2 border-surface-mid rounded-full hover:border-primary/40 transition-colors"
                    >
                        Kayıt Ol
                    </Link>
                </div>
            </div>
        );
    }

    const totalChallengeSent = profile.challengeStats.reduce((s, c) => s + c.sent_count, 0);
    const totalChallengeReceived = profile.challengeStats.reduce((s, c) => s + c.received_count, 0);
    const totalChallengeWon = profile.challengeStats.reduce((s, c) => s + c.won_count, 0);
    const bestChallengeScore = profile.challengeStats.reduce((m, c) => Math.max(m, c.best_score), 0);
    const challengeWinRate = totalChallengeReceived > 0
        ? Math.round((totalChallengeWon / totalChallengeReceived) * 100)
        : 0;

    return (
        <div className="space-y-6">
            {/* Özet Kartlar */}
            <div className="space-y-4">
                <h2 className="text-lg font-black text-text-main flex items-center gap-2">
                    <Swords size={20} className="text-primary" />
                    Meydan Okuma Özeti
                </h2>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                    <StatCard label="Gönderilen" value={totalChallengeSent} icon={<SendHorizonal size={20} />} />
                    <StatCard label="Katılınan" value={totalChallengeReceived} icon={<Users size={20} />} />
                    <StatCard label="Kazanılan" value={totalChallengeWon} icon={<Trophy size={20} />} highlight />
                    <StatCard label="En İyi Skor" value={bestChallengeScore > 0 ? bestChallengeScore : '—'} icon={<Star size={20} />} highlight />
                </div>
            </div>

            {/* Oyuna Göre Detay */}
            {profile.challengeStats.length > 0 ? (
                <div className="space-y-4">
                    <h2 className="text-lg font-black text-text-main flex items-center gap-2">
                        <BarChart3 size={20} className="text-primary" />
                        Oyuna Göre Detay
                    </h2>
                    <div className="grid gap-3">
                        {profile.challengeStats.map((stat) => {
                            const winRate = stat.received_count > 0
                                ? Math.round((stat.won_count / stat.received_count) * 100)
                                : 0;
                            return (
                                <div
                                    key={stat.game_name}
                                    className="bg-surface border-2 border-surface-mid rounded-2xl p-5"
                                >
                                    <div className="flex items-center justify-between mb-4">
                                        <h3 className="text-base font-bold text-text-main">
                                            {GAME_LABELS[stat.game_name] ?? stat.game_name}
                                        </h3>
                                        <span className="text-xs font-bold text-text-secondary bg-bg/50 px-3 py-1 rounded-full">
                                            %{winRate} başarı
                                        </span>
                                    </div>

                                    <div className="w-full h-2 bg-bg rounded-full mb-4 overflow-hidden">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${winRate}%` }}
                                            transition={{ duration: 0.8, ease: 'easeOut' }}
                                            className="h-full bg-gradient-to-r from-primary to-correct rounded-full"
                                        />
                                    </div>

                                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-center">
                                        <div>
                                            <p className="text-lg font-black text-text-main">{stat.sent_count}</p>
                                            <p className="text-[10px] text-text-secondary uppercase tracking-wider font-bold">Gönderilen</p>
                                        </div>
                                        <div>
                                            <p className="text-lg font-black text-text-main">{stat.received_count}</p>
                                            <p className="text-[10px] text-text-secondary uppercase tracking-wider font-bold">Katılınan</p>
                                        </div>
                                        <div>
                                            <p className="text-lg font-black text-correct">{stat.won_count}</p>
                                            <p className="text-[10px] text-text-secondary uppercase tracking-wider font-bold">Kazanılan</p>
                                        </div>
                                        <div>
                                            <p className="text-lg font-black text-primary">{stat.best_score > 0 ? stat.best_score : '—'}</p>
                                            <p className="text-[10px] text-text-secondary uppercase tracking-wider font-bold">En İyi Skor</p>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ) : (
                <div className="bg-surface border-2 border-surface-mid rounded-2xl p-8 text-center">
                    <Swords size={40} className="text-text-secondary mx-auto mb-3 opacity-40" />
                    <p className="text-text-secondary text-sm mb-4">Henüz bir meydan okumaya katılmadın.</p>
                </div>
            )}

            {/* Kazanma Oranı Banner */}
            {totalChallengeReceived > 0 && (
                <div className="bg-gradient-to-br from-primary/5 to-primary/10 border-2 border-primary/20 rounded-2xl p-5">
                    <div className="flex items-center justify-between mb-3">
                        <p className="text-sm font-bold text-text-main">Genel Meydan Okuma Başarısı</p>
                        <span className="text-xl font-black text-primary">%{challengeWinRate}</span>
                    </div>
                    <div className="w-full h-3 bg-bg rounded-full overflow-hidden">
                        <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${challengeWinRate}%` }}
                            className="h-full bg-gradient-to-r from-primary to-correct rounded-full"
                        />
                    </div>
                </div>
            )}
        </div>
    );
}

